/**
 * Milestone domain rules that do not belong to the data layer: the conflict
 * error every state-machine refusal maps to, name comparison (case and
 * surrounding-space insensitive) and the listing order / overdue predicate.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export type MilestoneStateErrorReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const MESSAGE_BY_REASON: Readonly<Record<MilestoneStateErrorReason, string>> = {
  closed: "That milestone is closed.",
  already_open: "That milestone is already open.",
  too_many_open: "This project already has the maximum number of open milestones.",
  name_taken: "A milestone with that name already exists in this project.",
};

/** Thrown for every milestone state-machine refusal; mapped to `conflict`. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateErrorReason) {
    super(MESSAGE_BY_REASON[reason]);
    this.name = "MilestoneStateError";
  }
}

/** Names are compared without regard to letter case or surrounding spaces. */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}

export function sameMilestoneName(a: string, b: string): boolean {
  return normalizeMilestoneName(a) === normalizeMilestoneName(b);
}

/**
 * Open first, then closed; within each group by target date (earliest
 * first, no-target-date last); ties by creation, oldest first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const aOpen = a.closedAt === null;
  const bOpen = b.closedAt === null;
  if (aOpen !== bOpen) return aOpen ? -1 : 1;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    return a.targetDate < b.targetDate ? -1 : 1;
  }

  if (a.createdAt !== b.createdAt) {
    return a.createdAt < b.createdAt ? -1 : 1;
  }
  return 0;
}

/** Open, with a target date strictly in the past, and still has open issues. */
export function isMilestoneOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date = new Date(),
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (progress.open === 0) return false;
  return milestone.targetDate < toIsoTimestamp(now);
}

