/**
 * Milestone rows: creation, rename/target-date updates, close/reopen, and the
 * live-issue progress rollup `MilestoneService` turns into `overdue`.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, count, eq, inArray, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { CreateMilestoneInput, UpdateMilestoneInput } from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of the project, open and closed alike, unsorted. */
export async function listMilestonesByProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name.trim(),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined ? {} : { name: input.name.trim() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(milestones)
    .set({ closedAt: stamp, updatedAt: stamp })
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/** Counted over the milestone's live (non-archived) issues only. */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneProgress> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.milestoneId, milestoneId),
    isNull(issues.archivedAt),
  );

  const total = db.select({ value: count() }).from(issues).where(scope).get();
  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const totalCount = total?.value ?? 0;
  const closedCount = closed?.value ?? 0;

  return { total: totalCount, open: totalCount - closedCount, closed: closedCount };
}

