  return issueRepo.setIssueMilestone(input.orgId, input.issueId, input.milestoneId);
}

/**
 * The milestone must belong to the issue's own project and be open. Shared by
 * `createIssue` and `setIssueMilestone` so the refusal is identical either way.
 */
async function assertMilestoneAcceptsIssue(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: Issue["milestoneId"] & {},
): Promise<void> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );

  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
}

