    await assertNameAvailable(input.orgId, before.projectId, input.name, before.id);
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closing relocates the milestone's open live issues to `moveOpenIssuesTo`
 * (another open milestone of the same project) or out of any milestone, when
 * none is named. Closed and archived issues stay where they are.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const target = await resolveCloseTarget(
    input.orgId,
    milestone,
    input.moveOpenIssuesTo,
  );

  const moved = await issueRepo.moveOpenIssuesToMilestone(
    input.orgId,
    milestone.id,
    target ? target.id : null,
  );
  const closed = await milestoneRepo.closeMilestone(input.orgId, milestone.id);
  const movedIssueIds = moved.map((row) => row.id);

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: target ? target.id : null,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

