  }

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestoneId);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

