import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/0bf1285e-3d24-4601-8172-0add05ee7415/tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/0bf1285e-3d24-4601-8172-0add05ee7415/tests/server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/0bf1285e-3d24-4601-8172-0add05ee7415/tests/server/_support/fixtures";
import type { Tenant } from "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/0bf1285e-3d24-4601-8172-0add05ee7415/tests/server/_support/fixtures";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milecheck");
});

afterAll(() => {
  cleanup();
});

describe("milestone smoke", () => {
  it("creates, lists in order, enforces name uniqueness and the open cap", async () => {
    const m1 = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Launch",
      targetDate: null,
    });

    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "  launch ",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });

    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "Viewer attempt",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const m2 = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Beta",
      targetDate: "2026-01-01T00:00:00.000Z" as never,
    });

    const list = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      tenant.project.id,
    );
    // m2 has a target date, m1 doesn't -> m2 first among open.
    expect(list.map((x) => x.milestone.id)).toEqual([m2.id, m1.id]);

    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT - 2; i++) {
      await milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: `Filler ${i}`,
        targetDate: null,
      });
    }

    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "One too many",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });

  it("moves open issues on close, notifies assignees, records audit + overdue", async () => {
    const target = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Target milestone",
      targetDate: null,
    });
    const source = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Source milestone",
      targetDate: "2020-01-01T00:00:00.000Z" as never,
    });

    const openIssue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Open issue" }),
      assigneeId: tenant.userIds.admin,
      milestoneId: source.id,
    } as never);

    const closedIssue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Closed issue" }),
      assigneeId: tenant.userIds.viewer,
      milestoneId: source.id,
    } as never);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: closedIssue.id,
      status: "done",
    });

    const before = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      source.id,
    );
    expect(before.progress).toEqual({ total: 2, open: 1, closed: 1 });
    expect(before.overdue).toBe(true); // target date in the past and has an open issue

    const events: unknown[] = [];
    const off = require("@/lib/event-bus").subscribe("milestone.closed", (p: unknown) => {
      events.push(p);
    });

    const result = await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });
    off();

    expect(result.movedIssueIds).toEqual([openIssue.id]);
    expect(events).toHaveLength(1);

    const movedIssue = await issueService.getIssue(
      tenant.actors.viewer,
      tenant.org.id,
      openIssue.id,
    );
    expect(movedIssue.issue.milestoneId).toBe(target.id);

    const stillClosedIssue = await issueService.getIssue(
      tenant.actors.viewer,
      tenant.org.id,
      closedIssue.id,
    );
    expect(stillClosedIssue.issue.milestoneId).toBe(source.id); // closed issues stay put

    // closing again is refused
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toMatchObject({ reason: "closed" });

    // reopening the already-open target is refused
    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, target.id),
    ).rejects.toMatchObject({ reason: "already_open" });

    const reopened = await milestoneService.reopenMilestone(
      tenant.actors.admin,
      tenant.org.id,
      source.id,
    );
    expect(reopened.closedAt).toBeNull();

    // the admin's own assignee for openIssue is admin -> admin shouldn't be notified about their own close trigger.
    const adminNotifications = await notificationService.listNotifications(
      tenant.actors.admin,
      {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        kind: ["issue_milestone_changed"],
        limit: 25,
        cursor: null,
      },
    );
    // admin closed the milestone AND admin is the assignee of the moved issue -> not notified.
    expect(adminNotifications.items).toHaveLength(0);
  });

  it("refuses moving an issue into a closed or foreign-project milestone", async () => {
    const otherTenant = await createTenant("milecheck-other");
    const foreignMilestone = await milestoneService.createMilestone(
      otherTenant.actors.member,
      { orgId: otherTenant.org.id, projectId: otherTenant.project.id, name: "Foreign", targetDate: null },
    );

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mover" }),
    );

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreignMilestone.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const closedMilestone = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "ToClose",
      targetDate: null,
    });
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closedMilestone.id,
      moveOpenIssuesTo: null,
    });

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: closedMilestone.id,
      }),
