/**
 * Milestone lifecycle: creation under the open-milestone cap, rename/target
 * date edits, closing (which relocates the milestone's open live issues) and
 * reopening.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, requireFound, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  compareMilestones,
  isMilestoneOverdue,
  sameMilestoneName,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError, actorEnvelope, projectResource, requireFound } from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Actor } from "@/types/member";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const openCount = await milestoneRepo.countOpenMilestones(
    input.orgId,
    input.projectId,
  );
  if (openCount >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  await assertNameAvailable(input.orgId, input.projectId, input.name, null);

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, before.projectId),
    "Project",
    before.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.name !== undefined) {
    await assertNameAvailable(input.orgId, before.projectId, input.name, before.id);
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closing relocates the milestone's open live issues to `moveOpenIssuesTo`
 * (another open milestone of the same project) or out of any milestone, when
 * none is named. Closed and archived issues stay where they are.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const target = await resolveCloseTarget(
    input.orgId,
    milestone,
    input.moveOpenIssuesTo,
  );

  const moved = await issueRepo.moveOpenIssuesToMilestone(
    input.orgId,
    milestone.id,
    target ? target.id : null,
  );
  const closed = await milestoneRepo.closeMilestone(input.orgId, milestone.id);
  const movedIssueIds = moved.map((row) => row.id);

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: target ? target.id : null,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }

  const openCount = await milestoneRepo.countOpenMilestones(
    orgId,
    milestone.projectId,
  );
  if (openCount >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestoneId);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [...(await milestoneRepo.listMilestonesByProject(orgId, projectId))]
    .sort(compareMilestones);

  return Promise.all(milestones.map((milestone) => withProgress(orgId, milestone)));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  return withProgress(orgId, milestone);
}

async function withProgress(
  orgId: OrgId,
  milestone: Milestone,
): Promise<MilestoneWithProgress> {
  const progress = await milestoneRepo.getMilestoneProgress(orgId, milestone.id);
  return { milestone, progress, overdue: isMilestoneOverdue(milestone, progress) };
}

/** Names are unique per project, closed milestones included, case/space insensitive. */
async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  excludeMilestoneId: MilestoneId | null,
): Promise<void> {
  const existing = await milestoneRepo.listMilestonesByProject(orgId, projectId);
  const taken = existing.some(
    (candidate) =>
      candidate.id !== excludeMilestoneId && sameMilestoneName(candidate.name, name),
  );
  if (taken) {
    throw new MilestoneStateError("name_taken");
  }
}

/**
 * The close target, resolved and validated: must be another open milestone
 * of the same project. `null` means "take the issues out of any milestone."
 */
async function resolveCloseTarget(
  orgId: OrgId,
  milestone: Milestone,
  moveOpenIssuesTo: MilestoneId | null,
): Promise<Milestone | null> {
  if (moveOpenIssuesTo === null) return null;

  if (moveOpenIssuesTo === milestone.id) {
    throw new NotFoundError("Milestone", moveOpenIssuesTo);
  }

  const target = await milestoneRepo.findMilestoneById(orgId, moveOpenIssuesTo);
  if (target === null || target.projectId !== milestone.projectId) {
    throw new NotFoundError("Milestone", moveOpenIssuesTo);
  }
  if (target.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  return target;
}
